import java.util.*;

/**
 * Created by naveen on 19-Dec-15.
 */
public class test {

    public static void main(String[] args) {

        Scanner scn = new Scanner(System.in);

        int n = Integer.parseInt(scn.nextLine());
        String ip = scn.nextLine();

        int wordCount = 0;
        int longestWord = 0;

        boolean insideBraces = false;

        StringBuilder stringBuilder = new StringBuilder("");

        for (int i = 0; i < n; i++) {
            char ch = ip.charAt(i);

            if(ch == '_') {
                int wordLength = stringBuilder.length();

                if(wordLength > 0) {
                    if(insideBraces) {
                        wordCount++;
                    }
                    else {
                        longestWord = Math.max(longestWord, wordLength);
                    }
                }

                stringBuilder = new StringBuilder("");
            }

            if(ch == '(') {
                int wordLength = stringBuilder.length();

                if(wordLength > 0) {
                    if(insideBraces) {
                        wordCount++;
                    }
                    else {
                        longestWord = Math.max(longestWord, wordLength);
                    }
                }

                stringBuilder = new StringBuilder("");
                insideBraces = true;
            }

            if(ch == ')') {
                int wordLength = stringBuilder.length();

                if(wordLength > 0) {
                    if(insideBraces) {
                        wordCount++;
                    }
                    else {
                        longestWord = Math.max(longestWord, wordLength);
                    }
                }

                stringBuilder = new StringBuilder("");
                insideBraces = false;
            }

            if((ch >= 'a' && ch <= 'z')
                || (ch >= 'A' && ch <= 'Z'))
                stringBuilder.append(ch);

        }

        int wordLength = stringBuilder.length();

        if(wordLength > 0) {
            if(insideBraces) {
                wordCount++;
            }
            else {
                longestWord = Math.max(longestWord, wordLength);
            }
        }

        System.out.println(longestWord + " " + wordCount);

    }

}

